+
+    .actions {
+      display: flex;
+      justify-content: flex-end;
+      margin-top: 24px;
+    }
+
+    button {
+      border: 0;
+      border-radius: 999px;
+      padding: 14px 22px;
+      font: inherit;
+      font-weight: 700;
+      color: white;
+      background: linear-gradient(135deg, var(--accent), #4f46e5);
+      box-shadow: 0 10px 24px rgba(124, 58, 237, 0.28);
+      cursor: pointer;
+      transition: transform 160ms ease, filter 160ms ease;
