           <div class="question-header">
             <div>
               <h2 class="question-title">${question}</h2>
               ${helpText ? `<p class="help-text">${helpText}</p>` : ""}
             </div>
           </div>
           <div class="choices">
             ${options.map((option) => Choice({ questionId: id, option })).join("")}
           </div>
         </div>
       `;
     }

     function QuizApp() {
       return `
         <main class="app">
           <section class="hero">
             <p class="eyebrow">Knowledge check</p>
             <h1>Computer Languages Quiz</h1>
             <p class="subtitle">Select every answer that fits each question. There may be more than one correct choice per prompt.</p>
           </section>
           <form id="quiz-form">
             ${quizData.map((item) => Question(item)).join("")}
             <div class="actions">
               <button type="submit">Submit Quiz</button>
             </div>
             <div class="result" id="result" aria-live="polite"></div>
           </form>
         </main>
       `;
     }

     document.getElementById("root").innerHTML = QuizApp();

     document.getElementById("quiz-form").addEventListener("submit", (event) => {
       event.preventDefault();
       document.getElementById("result").textContent = "Submitted. Nice work!";
     });
   </script>
 </body>
 </html>

')
